function initialNavigation(state: StoredState) {
  const params = new URLSearchParams(location.search);
  if (params.get('trip') === state.journey!.id && params.has('kind')) {
    const kind = params.get('kind'), id = params.get('object');
    const matches = projectProgram(state).filter(item => item.kind === kind && item.id === id);
    if (kind === 'step' && matches.length === 1) return { cityId: matches[0].cityId, dayId: matches[0].dayId || '', view: 'planning' as const, stepId: matches[0].id };
    if (kind === 'transfer' && matches.length === 1) return { cityId: matches[0].cityId, dayId: '', view: 'transport' as const };
    if (kind === 'recap' && id && projectProgram(state).some(item => item.date === id)) return { cityId: state.cities[0]?.id || '', dayId: state.cities[0]?.days[0]?.id || '', view: 'planning' as const, recapDate: id };
    return { cityId: state.cities[0]?.id || '', dayId: state.cities[0]?.days[0]?.id || '', view: 'planning' as const, linkError: true };
  }
  try {
    const raw = sessionStorage.getItem(`a-l-est-navigation-v2:${state.journey!.id}`);
    if (raw) {
      const value = JSON.parse(raw);
      if (value && typeof value.cityId === 'string' && typeof value.dayId === 'string' && navItems.some(item=>item.id===value.view)) return value as NonNullable<StoredState['resume']> & { stepId?: string; recapDate?: string; linkError?: boolean };
    }
  } catch { /* The journal's saved selection is still available. */ }
  return state.resume as (NonNullable<StoredState['resume']> & { stepId?: string; recapDate?: string; linkError?: boolean }) | undefined;
}
type ModalState = { type: 'city'; city?: City } | { type: 'step'; step?: Step; day: Day } | { type: 'day'; day?: Day } | { type: 'bonus'; bonus: Bonus } | { type: 'bonus-editor'; bonus?: Bonus } | { type: 'document'; document: TravelDocument } | { type: 'source'; kind: 'planning' | 'bonus' } | { type: 'confirm'; title: string; description: string; action: () => void } | null;

export function Modal({ title, children, onClose, wide = false, returnFocus }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean; returnFocus?: HTMLElement | null }) {
  const { t } = useLocale();
  const ref = useRef<HTMLDivElement>(null);
  // Capture the trigger before an autoFocus field takes focus during the portal commit.
  const previousFocus = useRef(returnFocus || document.activeElement as HTMLElement | null);
  const { dismiss, grabberProps } = useSheetMotion(ref, onClose);
  const closeRef = useRef(dismiss); closeRef.current = dismiss;
  useEffect(() => {
    const previous = previousFocus.current;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    ref.current?.focus();
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeRef.current();
      if (event.key !== 'Tab') return;
      const focusables = Array.from(ref.current?.querySelectorAll<HTMLElement>('button, a[href], input, select, textarea, [tabindex="0"]') || []).filter(el => !el.hasAttribute('disabled') && el.getClientRects().length > 0);
      const first = focusables[0], last = focusables[focusables.length - 1];
      if (event.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && (document.activeElement === last || document.activeElement === ref.current)) { event.preventDefault(); first?.focus(); }
    };
    document.addEventListener('keydown', key);
    return () => {
      document.removeEventListener('keydown', key);
      document.body.style.overflow = previousOverflow;
      // A sharing sheet can replace its details sheet, removing the old trigger.
      const fallback = ['.trip-summary button', '.topbar button[aria-controls="sidebar"]', '.trip-menu-actions button']
        .map(selector => document.querySelector<HTMLElement>(selector)).find(el => el?.getClientRects().length);
      const target = previous?.isConnected && previous.getClientRects().length ? previous : fallback;
      target?.focus({preventScroll:true});
    };
  }, []);
  return createPortal(<div className="modal-backdrop" onClick={e => { if (e.target === e.currentTarget) dismiss(); }}><div className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title" tabIndex={-1} ref={ref}><div className="sheet-grabber" aria-hidden="true" {...grabberProps}/><div className="modal-heading"><h2 id="modal-title">{title}</h2><button className="icon-btn" onClick={dismiss} aria-label={t("Fermer")}><X size={20}/></button></div><div className="modal-content">{children}</div></div></div>, document.body);
}

const LazySourceDocument = lazy(() => import('./components/SourceDocument'));
function SourceDocument(props: ComponentProps<typeof LazySourceDocument>) {
  const { t } = useLocale();
  return <Suspense fallback={<p role="status">{t('Chargement…')}</p>}><LazySourceDocument {...props}/></Suspense>;
}

export default function App({ seed, onHome, onImport, externalError, accountControl, readOnly = false, allowedFields, collaborationControl }: { externalError?: string; seed: StoredState; onHome: () => void; onImport: (file: File) => Promise<void>; accountControl?: ReactNode; readOnly?: boolean; allowedFields?: string[]; collaborationControl?: ReactNode | ((local: { saving: boolean; storageError: string; summary: boolean; menuTarget: HTMLDivElement | null; onAction: () => HTMLElement | null }) => ReactNode) }) {
  const { t, dateLocale, language } = useLocale();
  const { provider } = useMapPreferences();
  const { state, setState, replaceState, storageError, corruptRaw, recovery, syncMessage, setSyncMessage, saving } = useTravelState(seed, readOnly);
  const [navigation] = useState(()=>initialNavigation(state));
  const [view, setView] = useState<View>(navigation?.view || 'planning');
  const journey = state.journey!;
  const isChina = journey.source === 'china';
  const [cityId, setCityId] = useState(navigation?.cityId || state.cities[0]?.id || '');
  const [dayId, setDayId] = useState(navigation?.dayId || state.cities[0]?.days[0]?.id || '');
  const [selectedStepId, setSelectedStepId] = useState(navigation?.stepId || '');
  const [query, setQuery] = useState('');
  const [bonusCategory, setBonusCategory] = useState('all');
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const mobileMenuTrigger = useRef<HTMLButtonElement>(null);
  const [collaborationMenu, setCollaborationMenu] = useState<HTMLDivElement | null>(null);
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState(navigation?.linkError ? notificationCopy(language, 'missingTarget') as string : '');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [mapOverview, setMapOverview] = useState(true);
  const emptyCity: City = { id: '', name: '', chineseName: '', subtitle: '', image: '/travel-landscape.svg', color: '#547764', days: [], notes: [], mapProvider: 'google' };
  const city = state.cities.find(c => c.id === cityId) || state.cities[0] || emptyCity;
  const mapLabel = provider === 'google' ? 'Google Maps' : 'Amap';
  const day = city.days.find(d => d.id === dayId) || city.days[0];
  const plannedSteps = day ? activeSteps(day) : [];
  const totalDays = state.cities.reduce((n, c) => n + c.days.length, 0);
  const allBonus = [...(state.bonusCatalog || []), ...(state.customBonus || [])].filter(b => state.cities.some(c=>c.id===b.cityId));
  const cityBonus = allBonus.filter(b => b.cityId === city.id);
  const dayIndex = city.days.findIndex(d => d.id === day?.id);
  const doneCount = city.days.flatMap(d => d.steps).filter(s => state.done.includes(s.id)).length;
  const citySteps = city.days.flatMap(d => d.steps);
  // Recompute the civil date each render, once per distinct zone, not per day.
  // This render-local cache cannot outlive midnight or leak across accounts.
  const todayByTimezone = new Map<string, string>();
  const todayStops=state.cities.flatMap(c => {
    const zone = c.timezone || journey.timezone;
    let today = todayByTimezone.get(zone);
    if (!today) { today = dateInTimezone(zone); todayByTimezone.set(zone, today); }
    return c.days.filter(d => d.date === today).map(d => ({city:c,day:d}));
  });
  const todayStop=todayStops.find(stop => activeSteps(stop.day).some(step => !state.done.includes(step.id))) || todayStops[0];
  const resumeDay = city.days.find(d => d.steps.some(step => !state.done.includes(step.id)));
  const shortcut = todayStop || (resumeDay ? { city, day: resumeDay } : undefined);
  const sourceLabel = modal?.type === 'document' ? modal.document.title : modal?.type === 'source' ? (modal.kind === 'planning' ? t('Ton planning original') : t('Ton carnet de bonus original')) : '';
  useEffect(() => {
    for (const selector of ['.city-tabs .city-tab.active', '.day-tabs button.active']) {
      const active = document.querySelector<HTMLElement>(selector), container = active?.parentElement;
      if (!active || !container || container.scrollWidth <= container.clientWidth) continue;
      const item = active.getBoundingClientRect(), bounds = container.getBoundingClientRect();
      if (item.left < bounds.left || item.right > bounds.right) container.scrollTo({ left: container.scrollLeft + item.left - bounds.left - (bounds.width - item.width) / 2, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    }
  }, [city.id, day?.id, view]);
  useEffect(() => { if (syncMessage) { setToast(syncMessage); setSyncMessage(''); } }, [syncMessage, setSyncMessage]);
  useEffect(() => {
    if (!mobileMenu) return;
    const before=document.activeElement as HTMLElement|null;
    const sidebar=document.getElementById('sidebar');
    const focusable=()=>Array.from(sidebar?.querySelectorAll<HTMLElement>('a[href],button')||[]).filter(el=>el.getClientRects().length>0 && !el.hasAttribute('disabled'));
    focusable()[0]?.focus();
    const keys=(event:KeyboardEvent)=> { if(event.key==='Escape') {event.preventDefault();setMobileMenu(false);} if(event.key==='Tab') {const items=focusable();const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}} };
    const overflow=document.body.style.overflow;document.body.style.overflow='hidden';
    document.addEventListener('keydown',keys);
    return ()=>{document.removeEventListener('keydown',keys);document.body.style.overflow=overflow;before?.focus();};
  },[mobileMenu]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 3500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const online = () => setIsOnline(navigator.onLine); window.addEventListener('online', online); window.addEventListener('offline', online); return () => { window.removeEventListener('online', online); window.removeEventListener('offline', online); }; }, []);
  useEffect(() => { document.title = `Détours — ${journey.title}`; }, [journey.title, t]);
  useEffect(() => {
    const resume = { cityId: city.id, dayId: day?.id || '', view };
    try {sessionStorage.setItem(`a-l-est-navigation-v2:${journey.id}`,JSON.stringify(resume));}catch { /* Global journal selection remains the fallback. */ }
    // Navigation stays in this tab; it never creates a shared data revision.
  }, [city.id, day?.id, view, setState]);
  function chooseCity(c: City) { setCityId(c.id); setDayId(c.days[0]?.id || ''); setSelectedStepId(''); }
  function jumpToNext() {
    if (!shortcut) return;
    const step = activeSteps(shortcut.day).find(item => !state.done.includes(item.id));
    setCityId(shortcut.city.id); setDayId(shortcut.day.id); setSelectedStepId(step?.id || ''); navigate('planning');
    requestAnimationFrame(() => requestAnimationFrame(() => {
      const target = step ? document.getElementById(`step-${step.id}`) : document.querySelector('.day-panel');
      target?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center' });
    }));
  }
  function navigate(next: View) { if (next !== view) window.scrollTo({ top: 0, behavior: 'instant' }); setView(next); setQuery(''); setMobileMenu(false); }
  function changeCity(updated: City) { setState(s => ({ ...s, cities: s.cities.map(c => c.id === updated.id ? updated : c) })); }
  function changeDay(updated: Day) { changeCity({ ...city, days: city.days.map(d => d.id === updated.id ? updated : d) }); }
  function toggleDone(id: string) { setState(s => ({ ...s, done: toggleValue(s.done, id) })); }
  function toggleFavorite(id: string) { setState(s => ({ ...s, favorites: toggleValue(s.favorites, id) })); }
  function moveStep(step: Step, direction: number) { if (!day) return; const steps = [...day.steps]; const idx = steps.findIndex(s => s.id === step.id); const target = idx + direction; if (target < 0 || target >= steps.length) return; [steps[idx], steps[target]] = [steps[target], steps[idx]]; changeDay({ ...day, steps }); }
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); setToast(t('Texte copié.')); } catch { setToast(t('Copie indisponible : sélectionne le nom affiché pour le copier.')); } }
  function exportData() { downloadText(JSON.stringify(archive(state), null, 2), `a-l-est-${journey.id}.json`); setToast(t('Ton carnet a été exporté.')); }
  function exportOriginal() { if(corruptRaw) downloadText(corruptRaw,'a-l-est-sauvegarde-a-recuperer.json'); }
  async function importData(file: File) { await onImport(file); }
  function addBonusToDay(bonus: Bonus) { if (!day) { setToast(t('Crée une journée dans cette ville avant d’ajouter un bonus.')); return; } const step: Step = { id: uid('step'), title: bonus.title, chineseName: bonus.chineseName, address: bonus.address, description: [bonus.description, bonus.tip].filter(Boolean).join('\n'), category: bonus.category === 'photo' ? 'visit' : bonus.category, amapUrl: bonus.amapUrl }; changeDay({ ...day, steps: [...day.steps, step] }); setModal(null); setToast(t('Ajouté au jour {day} de {city}.', { day: dayIndex + 1, city: city.name })); }
  const normalized = normalizeSearch(query.trim());
  const searchResults = normalized ? state.cities.flatMap(c => c.days.flatMap(d => d.steps.filter(s => normalizeSearch(`${s.title} ${s.chineseName || ''} ${s.address || ''} ${s.description} ${c.name}`).includes(normalized)).map(s => ({ city: c, day: d, step: s })))).slice(0, 20) : [];
  const searchBonus = normalized ? allBonus.filter(b => normalizeSearch(`${b.title} ${b.chineseName || ''} ${b.address || ''} ${b.description} ${state.cities.find(c=>c.id===b.cityId)?.name || ''}`).includes(normalized)).slice(0, 12) : [];
  const filteredBonus = (favoritesOnly ? allBonus : cityBonus).filter(b => (bonusCategory === 'all' || b.category === bonusCategory) && (!favoritesOnly || state.favorites.includes(b.id)));

  function cityForm(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget); const existing = modal?.type === 'city' ? modal.city : undefined;
    const lat=String(form.get('lat')||''),lng=String(form.get('lng')||'');
    if(Boolean(lat)!==Boolean(lng)) {setToast(t('Renseigne les deux coordonnées ou laisse-les vides.'));return;}
    const coordinates: [number,number]|undefined=lat&&lng ? [Number(lat),Number(lng)] : undefined;
    const next: City = { id: existing?.id || uid('city'), name: String(form.get('name')).trim(), chineseName: String(form.get('chineseName')).trim(), subtitle: String(form.get('subtitle')).trim() || 'Une nouvelle étape à imaginer', color: existing?.color || '#547764', image: existing?.image || journey.cover, mapProvider: existing?.mapProvider, timezone: String(form.get('timezone') || '').trim() || undefined, coordinates, days: existing?.days || [], notes: String(form.get('notes') || '').split('\n').map(x => x.trim()).filter(Boolean), ...(String(form.get('nights')||'') ? { nights: Number(form.get('nights')) } : {}) };
    if (!next.name) return;
    const position=Number(form.get('position'));
    setState(s=>{const cities=s.cities.filter(c=>c.id!==next.id);const latest=s.cities.find(c=>c.id===next.id);cities.splice(Math.min(position,cities.length),0,latest && existing ? mergeChanges(existing,next,latest) : next);return {...s,cities};});
    if(!existing){chooseCity(next);setView('planning');}
    setModal(null); setToast(existing ? t('Ville mise à jour.') : t('Nouvelle étape ajoutée.'));
  }
  function stepForm(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (modal?.type !== 'step') return; const form = new FormData(event.currentTarget); const title = String(form.get('title')).trim(); if (!title) return;
    const lat = String(form.get('lat') || ''), lng = String(form.get('lng') || '');
    if (Boolean(lat) !== Boolean(lng)) { setToast(t('Renseigne les deux coordonnées, ou laisse-les toutes les deux vides.')); return; }
    const step: Step = { id: modal.step?.id || uid('step'), title, chineseName: String(form.get('chineseName')).trim(), description: String(form.get('description')).trim(), address: String(form.get('address') || '').trim(), category: String(form.get('category')) as Category, period: String(form.get('period')).trim(), optional: form.get('optional') === 'on', booking: form.get('booking') === 'on', ...(lat && lng ? { coordinates: [Number(lat), Number(lng)] as [number, number] } : {}), ...(modal.step?.amapUrl && modal.step.title === title && modal.step.chineseName === String(form.get('chineseName')).trim() && (modal.step.address || '') === String(form.get('address') || '').trim() ? { amapUrl: modal.step.amapUrl } : {}) };
    const target=String(form.get('targetDay')||modal.day.id);
    if(target!==modal.day.id){changeCity({...city,days:city.days.map(d=>d.id===modal.day.id?{...d,steps:d.steps.filter(s=>s.id!==step.id)}:d.id===target?{...d,steps:[...d.steps,step]}:d)});setDayId(target);}
    else {setState(s=>({...s,cities:s.cities.map(c=>({...c,days:c.days.map(d=>d.id===modal.day.id?{...d,steps:modal.step?d.steps.map(item=>item.id===step.id && modal.step ? mergeChanges(modal.step,step,item) : item):[...d.steps,step]}:d)}))}));} setModal(null); setToast(t('Étape enregistrée.'));
  }
  function dayForm(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form=new FormData(event.currentTarget); const title=String(form.get('title')).trim(), date=String(form.get('date')||''); if(!title || (date&&!isValidDate(date))) return; const existing=modal?.type==='day'?modal.day:undefined; if(existing) {setState(s=>({...s,cities:s.cities.map(c=>({...c,days:c.days.map(d=>d.id===existing.id?mergeChanges(existing,{...existing,title,date},d):d)}))}));} else {const next={id:uid('day'),title,date,steps:[]};changeCity({...city,days:[...city.days,next]});setDayId(next.id);} setModal(null); }
  function bonusForm(event:FormEvent<HTMLFormElement>) {event.preventDefault();if(modal?.type!=='bonus-editor')return;const form=new FormData(event.currentTarget);const existing=modal.bonus;const bonus:Bonus={id:existing?.id||uid('bonus'),cityId:String(form.get('cityId')),title:String(form.get('title')).trim(),chineseName:String(form.get('chineseName')).trim(),address:String(form.get('address')).trim(),description:String(form.get('description')).trim(),category:String(form.get('category')) as Bonus['category'],budget:String(form.get('budget')).trim(),tip:String(form.get('tip')).trim()};if(!bonus.title)return;setState(s=>({...s,customBonus:existing?(s.customBonus||[]).map(b=>b.id===existing.id?mergeChanges(existing,bonus,b):b):[...(s.customBonus||[]),bonus]}));setModal(null);setToast(t('Adresse personnelle enregistrée.'));}


  return <SharedFieldsContext.Provider value={allowedFields}><ReadOnlyContext.Provider value={readOnly}><div className="app-shell" data-readonly={readOnly}>
    <a className="skip-link" href="#main">{t("Aller au contenu")}</a>
    {mobileMenu && <div className="sidebar-scrim" onClick={() => setMobileMenu(false)}/>}
    <aside inert={!!modal} id="sidebar" className={`sidebar ${mobileMenu ? 'open' : ''}`}>
      <a className="brand" href="#" onClick={e => { e.preventDefault(); navigate('planning'); }}><span className="brand-mark"><Mountain size={26} strokeWidth={1.6}/></span><span>détours<span className="brand-dot">.</span><small>{t("LES BEAUX DÉTOURS")}</small></span></a>
      <button className="journey-switch journey-back" disabled={saving} onClick={() => { if (storageError) exportData(); onHome(); }} aria-label={t("Mes voyages")}><span className="journey-flag">{isChina ? "中" : <Compass size={20}/>}</span><div><strong>{journey.title}</strong><span>{t("Mes voyages")}</span></div><ChevronLeft size={15}/></button>
      <p className="nav-caption">{t("MON VOYAGE")}</p>
      <nav className="glass-selection-group" aria-label={t("Navigation principale")}><GlassSelection selection={view}/>{navItems.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} aria-current={view === id ? 'page' : undefined} onClick={() => navigate(id)}><Icon size={19} strokeWidth={1.7}/><span>{t(label)}</span>{id === 'bonus' && <small>{state.favorites.length || '♡'}</small>}{view === id && <span className="nav-dot"/>}</button>)}</nav>
      <div className="trip-menu-actions" ref={setCollaborationMenu}/><div className="sidebar-route"><div className="sidebar-route-title"><span>{t("LE FIL DU VOYAGE")}</span><span>{state.cities.length} {t("étapes")}</span></div>{state.cities.map((c, index) => <button key={c.id} className={`route-stop ${c.id === city.id ? 'selected' : ''}`} onClick={() => { chooseCity(c); navigate('planning'); }}><span className="route-dot"/><span>{c.name}</span><small>{c.days.length ? t('{count} j', { count: c.days.length }) : t('à venir')}</small>{index === state.cities.length - 1 && <span className="sr-only">{t("Dernière étape")}</span>}</button>)}<EditButton className="route-add" onClick={() => { setModal({ type: 'city' }); setMobileMenu(false); }}><Plus size={14}/> {t("Ajouter une ville")}</EditButton></div>
      <div className="sidebar-bottom"><div className="mini-note"><span>{isChina ? "慢慢来" : <Compass size={22}/>}</span><p>{t("Prendre le temps.")}<br/>{t("Garder l’envie de découvrir.")}</p><Sparkles size={17}/></div><div className="local-status"><span className={`status-dot ${storageError ? 'warning' : ''}`}/>{storageError ? t('Export conseillé') : saving ? t('Enregistrement…') : t('Carnet sauvegardé sur cet appareil')}</div></div>
    </aside>
    <div className="workspace" inert={!!modal || mobileMenu}>
      <header className="topbar"><div className="breadcrumb"><button className="icon-btn mobile-only" ref={mobileMenuTrigger} aria-label={t("Ouvrir le menu")} aria-expanded={mobileMenu} aria-controls="sidebar" onClick={() => setMobileMenu(true)}><Menu size={21}/></button><span>{t("Mon carnet de voyage")}</span><ChevronRight size={14}/><strong>{journey.title}</strong></div><div className="topbar-actions"><label className="search-box"><Search size={17}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder={t("Retrouver un lieu, une envie…")} aria-label={t("Rechercher dans le carnet")}/>{query && <button onClick={() => setQuery('')} aria-label={t("Effacer la recherche")}><X size={14}/></button>}<span className="search-shortcut">⌕</span></label><button className="icon-btn help-btn" onClick={() => navigate('notebook')} aria-label={t("Informations pratiques")}><CircleHelp size={20}/></button><Suspense fallback={null}><RecapsButton state={state} requestedDate={navigation?.recapDate} onDay={item => { const current = projectProgram(state).filter(value => value.kind === item.kind && value.id === item.id); if (current.length !== 1) { setToast(notificationCopy(language, 'missingTarget')); return; } const target = current[0]; setCityId(target.cityId); if (target.dayId) setDayId(target.dayId); setSelectedStepId(target.kind === 'step' ? target.id : ''); navigate(target.kind === 'transfer' ? 'transport' : 'planning'); }}/></Suspense><PreferencesButton/>{accountControl}</div></header>
      <main id="main">{typeof collaborationControl === "function" ? collaborationControl({saving,storageError,summary:view==='planning',menuTarget:collaborationMenu,onAction:()=>{setMobileMenu(false);return mobileMenu?mobileMenuTrigger.current:null;}}) : collaborationControl}{externalError && <div className="notice warning-notice" role="alert">{externalError}</div>}
        {storageError && <div className="notice warning-notice" role="alert">{t(storageError)}<div className="recovery-actions"><button className="text-btn" onClick={corruptRaw ? exportOriginal : exportData}>{corruptRaw ? t('Télécharger le fichier original') : t('Exporter le carnet actuel')}</button>{recovery?.readable && <EditButton className="text-btn" onClick={()=>setModal({type:'confirm',title:t('Restaurer la copie précédente ?'),description:t('Cette copie automatique date du {date}. Elle remplacera le carnet actuel.', {date:new Date(recovery.savedAt).toLocaleString(dateLocale)}),action:()=>{replaceState(recoveryState(recovery.raw));setModal(null);setToast(t('Copie précédente restaurée.'));}})}>{t("Restaurer la copie précédente")}</EditButton>}</div></div>}
        {!isOnline && <div className="notice" role="status">{t("Tu es hors ligne. Ton planning et le fond général de la carte restent accessibles ; les cartes de rues et les liens externes nécessitent Internet.")}</div>}
        {normalized ? <section className="search-results"><div className="section-header"><div><p className="eyebrow">{t("DANS TON CARNET")}</p><h1>{t('À la recherche de « {query} »', { query })}</h1></div><button className="btn btn-secondary" onClick={() => setQuery('')}><X size={16}/> {t("Fermer")}</button></div><p className="muted">{t('{count} résultats affichés', { count: searchResults.length + searchBonus.length })}</p>{searchResults.map(result => <button className="search-result" key={result.step.id} onClick={() => { chooseCity(result.city); setDayId(result.day.id); setSelectedStepId(result.step.id); navigate('planning'); }}><MapPin size={20}/><div><strong>{result.step.title}</strong><span>{result.city.name} · {result.day.title}</span></div><ArrowRight size={17}/></button>)}{searchBonus.map(b => <button className="search-result" key={b.id} onClick={() => { const c = state.cities.find(c => c.id === b.cityId); if (c) chooseCity(c); navigate('bonus'); setModal({ type: 'bonus', bonus: b }); }}><Sparkles size={20}/><div><strong>{b.title}</strong><span>{t("Bonus ·")} {state.cities.find(c => c.id === b.cityId)?.name}</span></div><ArrowRight size={17}/></button>)}{!searchResults.length && !searchBonus.length && <div className="empty-state"><Search/><h3>{t("Aucun détour de ce nom")}</h3><p>{t("Essaie un autre lieu, un plat ou un nom chinois.")}</p></div>}</section> : <>
        <button type="button" className="btn btn-secondary now-shortcut" hidden={view === 'now'} onClick={() => navigate('now')}>{t('Voir Maintenant')}</button><section className="page-intro"><div><div className="eyebrow"><span className="tiny-line"/> {t("LE VOYAGE COMMENCE ICI")}</div><h1>{view === 'planning' ? t('Un grand voyage, de beaux détours.') : view === 'overview' ? t('Le voyage en un coup d’œil.') : view === 'practical' ? t('Les petits outils des grands voyages.') : view === 'map' ? t('Le voyage, étape par étape.') : view === 'bonus' ? t('Un peu de place pour l’imprévu.') : view === 'transport' ? t('D’une découverte à l’autre.') : t('L’essentiel, à portée de main.')}</h1><p>{view === 'planning' ? t('Tout ton itinéraire au même endroit. Il ne reste qu’à en profiter.') : view === 'overview' ? t('Choisis tes dates et garde une vue de tout ton parcours.') : view === 'practical' ? t('Hébergements, budget, valise et quelques mots pour se comprendre.') : view === 'map' ? t('Prends un peu de hauteur et retrouve les lieux de ton voyage.') : view === 'bonus' ? t('Tes bonnes adresses de réserve, à piocher selon l’envie et le temps.') : view === 'transport' ? t('Les liaisons de ton parcours et les détails à confirmer avant le départ.') : t('Tes réservations, tes notes et les petits détails qui changent tout.')}</p></div><div className="intro-actions">{shortcut && <button className="btn btn-secondary daily-shortcut" onClick={jumpToNext}><Navigation size={16}/>{t(todayStop ? 'Aujourd’hui' : 'Reprendre')}</button>}<button className="btn btn-secondary export-button" onClick={exportData}><Download size={16}/> {t("Exporter le carnet")}</button></div></section>
        {view === 'planning' && <section className={`hero ${isChina ? "" : "custom-hero"}`}><div className="hero-art" style={isChina ? undefined : { backgroundImage: `url(${JSON.stringify(journey.cover)})` }}/><div className="hero-copy"><span className="hero-pill"><span/> {isChina ? t("MON ÉCHAPPÉE EN ASIE") : journey.destinations || t("MON PROCHAIN DÉTOUR")}</span><h2>{isChina && journey.title === "Chine 2027" ? t("Cap sur la Chine") : journey.title}{isChina && <span>中国之旅</span>}</h2><p>{journey.description || t("Un voyage à imaginer, à ton rythme.")}</p><div className="hero-stats"><span><MapPin size={16}/>{state.cities.length} {t("villes & étapes")}</span><i/><span><CalendarDays size={16}/>{totalDays} {t("journées préparées")}</span>{(state.departureDate || isChina) && <><i/><span>{state.departureDate ? state.departureDate.slice(0,4) : "2027"}</span></>}</div></div><div className="hero-stamp"><Compass size={24} strokeWidth={1}/><span>{t("UN VOYAGE")}<br/>{t("À MON RYTHME")}</span></div><span className="hero-caption">{isChina ? t("L’esprit des paysages de Guilin · illustration") : t("Les beaux détours commencent ici.")}</span></section>}
        {(view === 'planning' || view === 'bonus' || view === 'map') && <section className="cities-section"><div className="section-label"><h2>{t("Les étapes du voyage")}</h2><span>{t("Un itinéraire qui grandit avec tes envies")}</span></div><div className="city-tabs" aria-label={t("Choisir une ville")}>{state.cities.map((c, index) => <button key={c.id} onClick={() => chooseCity(c)} className={`city-tab ${c.id === city.id ? 'active' : ''}`} aria-pressed={c.id === city.id}><span className="city-tab-number">{String(index + 1).padStart(2, '0')}</span><div><strong>{c.name}</strong><small>{c.days.length ? `${t(c.days.length === 1 ? '{count} jour' : '{count} jours', { count: c.days.length })}${c.nights !== undefined ? ` · ${t(c.nights === 1 ? '{count} nuit' : '{count} nuits', { count: c.nights })}` : t(' · excursion')}` : t('À compléter')}</small></div>{c.id === city.id && <span className="city-active-dot"/>}</button>)}<EditButton className="city-add" onClick={() => setModal({ type: 'city' })} aria-label={t("Ajouter une ville")}><Plus size={20}/></EditButton></div></section>}
        {view === 'planning' && state.cities.length > 0 && <section className="planning-section"><div className="city-heading"><div><div className="eyebrow">{t("ÉTAPE")} {String(state.cities.findIndex(c => c.id === city.id) + 1).padStart(2, '0')} <span className="heading-rule"/></div><h2>{city.name}<span>{city.chineseName}</span><EditButton className="icon-btn" aria-label={t('Modifier {name}', { name: city.name })} onClick={() => setModal({ type: 'city', city })}><Pencil size={15}/></EditButton></h2><p>{city.subtitle}</p></div><span className="progress-chip"><CheckCheck size={15}/>{doneCount} / {citySteps.length} {t("étapes vécues")}</span></div><div className="planning-grid"><div className="planning-main"><div className="day-tabs" aria-label={t("Choisir une journée")}>{city.days.map((d, index) => <button key={d.id} className={d.id === day?.id ? 'active' : ''} aria-pressed={d.id === day?.id} onClick={() => { setDayId(d.id); setSelectedStepId(''); }}><CalendarDays size={15}/> {t("Jour {count}", { count: index + 1 })}</button>)}<EditButton className="add-day" aria-label={t("Ajouter un jour")} onClick={() => setModal({ type: 'day' })}><Plus size={15}/><span>{t("Ajouter un jour")}</span></EditButton></div>{day ? <div className="day-panel panel"><div className="day-heading"><div><p className="eyebrow">{t("JOUR")} {String(dayIndex + 1).padStart(2, '0')} <span>· {plannedSteps.length} {t("étapes")}</span></p><h3>{day.title}</h3>{day.date && <p className="day-date">{new Date(day.date+'T12:00:00Z').toLocaleDateString(dateLocale,{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})}</p>}</div><div className="inline-actions"><EditButton className="icon-btn" aria-label={t("Modifier le titre de la journée")} onClick={() => setModal({ type: 'day', day })}><Pencil size={15}/></EditButton><EditButton className="icon-btn" aria-label={t("Supprimer cette journée")} onClick={() => setModal({ type: 'confirm', title: t('Supprimer cette journée ?'), description: t('« {name} » et ses {count} étapes seront retirées du planning.', { name: day.title, count: day.steps.length }), action: () => { changeCity({ ...city, days: city.days.filter(d => d.id !== day.id) }); setModal(null); } })}><Trash2 size={15}/></EditButton></div></div><DayPreparationPanel key={day.id} day={day} bookings={state.bookings} onSave={(base,preparation)=>setState(s=>({...s,cities:s.cities.map(c=>({...c,days:c.days.map(d=>d.id===base.id?{...d,preparation:mergeChanges(base.preparation||{},preparation,d.preparation||{})}:d)}))}))}/><div className="timeline">{plannedSteps.map((step, index) => { const Icon = categoryIcons[step.category]; const done = state.done.includes(step.id); const placeKnown=!!(step.chineseName||step.address||step.amapUrl||step.coordinates||(!['hotel','transport'].includes(step.category)&&!/^déjeuner$|^dîner|^pause$/i.test(step.title))); return <article id={`step-${step.id}`} key={step.id} className={`step-card ${selectedStepId === step.id ? 'highlighted' : ''} ${done ? 'is-done' : ''}`}><div className="timeline-rail"><EditButton category="preparation" aria-label={t(done ? 'Marquer à faire : {name}' : 'Marquer comme visité : {name}', { name: step.title })} aria-pressed={done} className={`step-check ${done ? 'checked' : ''}`} onClick={() => toggleDone(step.id)}>{done ? <Check size={15}/> : index + 1}</EditButton><span/></div><div className="step-content"><div className="step-meta"><span className={`category category-${step.category}`}><Icon size={12}/>{t(categoryLabels[step.category])}</span>{step.period && <span>{step.period}</span>}{step.optional && <span className="optional-tag">{t("Facultatif")}</span>}{step.booking && <span className="booking-tag">{state.bookings.includes(step.id) ? <Check size={11}/> : <Bookmark size={11}/>} {state.bookings.includes(step.id) ? t('Réservé') : t('À réserver')}</span>}</div><h4>{step.title}</h4>{step.chineseName && <p className="chinese-name">{step.chineseName}<button className="copy-btn" aria-label={t('Copier {name}', { name: step.chineseName })} onClick={() => copy(step.chineseName!)}><Copy size={11}/></button></p>}<p className="step-description">{step.description}</p>{step.address && <p className="step-address"><MapPin size={13}/>{step.address}</p>}<div className="step-bottom">{placeKnown ? <MapActions city={city} place={step} next={plannedSteps[index + 1]}/> : <EditButton className="text-btn address-missing" onClick={()=>setModal({type:'step',step,day})}>{t("Adresse à compléter")}</EditButton>}<div className="step-actions"><ReminderButton state={state} target={{kind:'step',id:step.id}} title={step.title} onDay={item=>{setCityId(item.cityId);setDayId(item.dayId||'');navigate('planning');}}/><EditButton className="icon-btn" aria-label={t('Monter {name}', { name: step.title })} disabled={!!day.preparation?.activeAlternativeId || index === 0} onClick={() => moveStep(step, -1)}><ArrowUp size={13}/></EditButton><EditButton className="icon-btn" aria-label={t('Descendre {name}', { name: step.title })} disabled={!!day.preparation?.activeAlternativeId || index === plannedSteps.length - 1} onClick={() => moveStep(step, 1)}><ArrowDown size={13}/></EditButton><EditButton className="icon-btn" aria-label={t('Modifier {name}', { name: step.title })} onClick={() => setModal({ type: 'step', step, day })}><Pencil size={13}/></EditButton><EditButton className="icon-btn" aria-label={t('Supprimer {name}', { name: step.title })} onClick={() => setModal({ type: 'confirm', title: t('Retirer cette étape ?'), description: t('« {name} » sera retiré de cette journée.', { name: step.title }), action: () => { changeDay({ ...day, steps: day.steps.filter(s => s.id !== step.id) }); setModal(null); } })}><Trash2 size={13}/></EditButton></div></div></div></article>; })}</div>{!day.steps.length && <div className="empty-state"><MapPin/><h3>{t("Une journée à imaginer")}</h3><p>{t("Ajoute ta première visite ou pioche dans tes bonus.")}</p></div>}<EditButton className="add-step" onClick={() => setModal({ type: 'step', day })}><Plus size={16}/> {t("Ajouter une étape à cette journée")}</EditButton><div className="day-footer"><span>{t("Pas d’horaires imposés. Profite à ton rythme.")}</span><div className="inline-actions"><button className="icon-btn" disabled={dayIndex === 0} aria-label={t("Jour précédent")} onClick={() => setDayId(city.days[dayIndex - 1].id)}><ChevronLeft size={17}/></button><button className="icon-btn" disabled={dayIndex === city.days.length - 1} aria-label={t("Jour suivant")} onClick={() => setDayId(city.days[dayIndex + 1].id)}><ChevronRight size={17}/></button></div></div></div> : <div className="panel empty-state city-empty"><Compass size={40}/><h3>{t('{city}, la suite de l’aventure', { city: city.name })}</h3><p>{t("Cette ville est prévue dans le voyage.")}<br/>{t("Son programme attend encore tes prochaines idées.")}</p><EditButton className="btn btn-primary" onClick={() => setModal({ type: 'day' })}><Plus size={16}/> {t("Créer ma première journée")}</EditButton></div>}</div><aside className="planning-aside"><div className="panel map-panel"><div className="panel-heading"><h3><MapPin size={16}/> {t("Les repères du jour")}</h3><button className="text-btn" onClick={() => { setView('map'); setMapOverview(false); }}>{t("Agrandir")} <ArrowUp size={12} className="rotate-arrow"/></button></div><div className="mini-map"><TripMap cities={state.cities} city={city} steps={plannedSteps} selectedStepId={selectedStepId} onSelectStep={id => { setSelectedStepId(id); document.getElementById(`step-${id}`)?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center' }); }}/></div></div><div className="remember-card"><div className="remember-heading"><span><Bookmark size={16}/></span><h3>{t("Le petit pense-bête")}</h3></div>{city.notes.length ? city.notes.map((note, index) => <p key={index}>{note}</p>) : <p>{t("Les détails de cette étape restent à préciser. Garde tes idées dans la note ci-dessous.")}</p>}<label className="sr-only" htmlFor="city-note">{t('Ma note pour {city}', { city: city.name })}</label><EditTextarea category="notes" id="city-note" value={state.notes[city.id] || ''} onChange={e => setState(s => ({ ...s, notes: { ...s.notes, [city.id]: e.target.value } }))} placeholder={t("Une idée, une adresse, un rappel…")} rows={2}/><span className="note-saved"><Check size={11}/> {t(allowedFields ? "Note du carnet · sauvegarde automatique" : "Note personnelle · sauvegarde locale")}</span></div><div className="bonus-teaser"><div className="teaser-icon"><Sparkles size={20}/></div><h3>{t("Et s’il reste un peu de temps ?")}</h3><p>{cityBonus.length ? t('{count} idées de restaurants, balades et jolis détours t’attendent à {city}.', { count: cityBonus.length, city: city.name }) : t('De nouvelles envies viendront bientôt compléter cette étape.')}</p><button onClick={() => navigate('bonus')} className="text-btn">{t("Explorer les bonus")} <ArrowRight size={14}/></button></div></aside></div></section>}
        {view === 'map' && <section className="full-map-section"><div className="section-header"><div><h2>{t("Les petits points d’un grand voyage")}</h2><p className="muted">{mapOverview ? t('Le fil de tes villes, dans l’ordre prévu.') : t('Les lieux préparés à {city}.', { city: city.name })}</p></div><div className="segmented"><button className={mapOverview ? 'active' : ''} onClick={() => setMapOverview(true)}>{t("Tout le voyage")}</button>{state.cities.length > 0 && <button className={!mapOverview ? 'active' : ''} onClick={() => setMapOverview(false)}>{city.name}</button>}</div></div><div className="full-map panel"><TripMap cities={state.cities} city={city} steps={citySteps} overview={mapOverview}/></div><div className="notice"><Navigation size={17}/><span>{t("Les repères donnent une vue d’ensemble. Ouvre les liens cartographiques pour les adresses exactes et les itinéraires. Les lieux sans coordonnées restent accessibles depuis le planning.")}</span></div></section>}
        {view === 'bonus' && state.cities.length > 0 && <section className="bonus-section"><div className="section-header"><div><p className="eyebrow">{t("LA LISTE DES « ET POURQUOI PAS ? »")}</p><h2>{favoritesOnly ? t('Mes favoris, toutes villes') : t('Les envies de {city}', { city: city.name })}<span className="count-badge">{favoritesOnly ? filteredBonus.length : cityBonus.length}</span></h2></div><div className="bonus-toolbar"><EditButton className="btn btn-secondary" onClick={()=>setModal({type:'bonus-editor'})}><Plus size={16}/> {t("Ajouter une adresse")}</EditButton><button className={`btn ${favoritesOnly ? 'btn-primary' : 'btn-secondary'}`} aria-pressed={favoritesOnly} onClick={() => setFavoritesOnly(!favoritesOnly)}><Heart size={16} fill={favoritesOnly ? 'currentColor' : 'none'}/> {t("Mes favoris")}</button></div></div><div className="bonus-filters">{[{ id: 'all', label: t('Toutes les envies'), Icon: Sparkles }, { id: 'food', label: t('À table'), Icon: Utensils }, { id: 'photo', label: t('Spots photo'), Icon: Camera }, { id: 'visit', label: t('À découvrir'), Icon: Compass }, { id: 'shopping', label: t('Shopping'), Icon: ShoppingBag }].map(({ id, label, Icon }) => <button key={id} aria-pressed={bonusCategory === id} className={bonusCategory === id ? 'active' : ''} onClick={() => setBonusCategory(current => current === id ? 'all' : id)}><Icon size={15}/>{t(label)}</button>)}</div><div className="bonus-grid">{filteredBonus.map(b => { const bonusCity=state.cities.find(c=>c.id===b.cityId)!; const Icon = categoryIcons[b.category]; return <article className="bonus-card panel" key={b.id}><div className="bonus-card-top"><span className={`bonus-category-icon category-${b.category}`}><Icon size={21}/></span><span className="eyebrow">{t(categoryLabels[b.category])}{favoritesOnly ? ` · ${bonusCity.name}` : ''}</span><EditButton category="preparation" aria-label={t(state.favorites.includes(b.id) ? 'Retirer des favoris : {name}' : 'Ajouter aux favoris : {name}', { name: b.title })} aria-pressed={state.favorites.includes(b.id)} className={`favorite-btn ${state.favorites.includes(b.id) ? 'is-favorite' : ''}`} onClick={() => toggleFavorite(b.id)}><Heart size={18} fill={state.favorites.includes(b.id) ? 'currentColor' : 'none'}/></EditButton></div><button className="bonus-card-title" onClick={() => {chooseCity(bonusCity);setModal({ type: 'bonus', bonus: b });}}><h3>{b.title}</h3></button>{b.chineseName && <p className="chinese-name">{b.chineseName}</p>}<p className="bonus-description">{b.description}</p>{b.budget && <span className="budget-tag">{b.budget}</span>}<div className="bonus-card-footer"><button className="text-btn" onClick={() => {chooseCity(bonusCity);setModal({ type: 'bonus', bonus: b });}}>{t("Tous les détails")} <ArrowRight size={13}/></button><a href={amapLink(preferredMapCity(bonusCity,provider), b)} target="_blank" rel="noreferrer" aria-label={t('Ouvrir {name} dans {map}', { name: b.title, map: provider === "google" ? "Google Maps" : "Amap" })} className="icon-btn"><Navigation size={16}/></a></div></article>; })}</div>{!filteredBonus.length && <div className="panel empty-state"><Heart size={32}/><h3>{favoritesOnly ? t('Une collection à commencer') : t('De nouveaux détours à imaginer')}</h3><p>{favoritesOnly ? t('Touche le cœur d’une adresse pour la retrouver ici.') : t('Pas encore de bonus dans cette catégorie pour cette ville.')}</p>{favoritesOnly && <button className="btn btn-secondary" onClick={() => setFavoritesOnly(false)}>{t("Voir toutes les envies")}</button>}</div>}{isChina && <p className="bonus-source-note">{t("Adresses issues de ton document. Les horaires, distinctions et succursales sont à revérifier avant le voyage.")} <button className="text-btn" onClick={() => setModal({ type: 'source', kind: 'bonus' })}>{t("Consulter les notes originales")} <ExternalLink size={12}/></button></p>}</section>}
        {!state.cities.length && ['planning','bonus'].includes(view) && <section className="panel empty-state empty-trip"><Compass size={40}/><h2>{t('Ton premier détour')}</h2><p>{t('Ajoute une ville, une région ou un lieu de séjour, puis prépare tes journées.')}</p><EditButton className="btn btn-primary" onClick={() => setModal({type:'city'})}><Plus size={16}/>{t('Ajouter une étape au voyage')}</EditButton></section>}
        {view === 'transport' && <TransportView state={state} onChange={setState} notify={setToast}/>}
        {view === 'now' && <NowView state={state} onNavigate={(cid,did,next)=>{setCityId(cid);setDayId(did);navigate(next);}} notify={setToast}/>}
        {view === 'overview' && <TripOverview state={state} onChange={setState} onNavigate={(cid,did)=>{setCityId(cid);setDayId(did);navigate('planning');}} notify={setToast}/>}
        {view === 'practical' && <PracticalView state={state} onChange={setState} notify={setToast}/>}
        {view === 'notebook' && <><OfflineStatus state={state} saving={saving} storageError={storageError}/>{recovery && <section className="panel recovery-panel"><h2>{t("Une copie de secours")}</h2><p className="muted">{t("Une copie du carnet avant une modification est conservée sur cet appareil. Dernière copie :")} {new Date(recovery.savedAt).toLocaleString(dateLocale)}.</p><div className="recovery-actions"><button className="btn btn-secondary" onClick={()=>downloadText(recovery.raw,'a-l-est-copie-precedente.json')}>{t("Télécharger la copie précédente")}</button>{recovery.readable && <EditButton className="btn btn-secondary" onClick={()=>setModal({type:'confirm',title:t('Restaurer la copie précédente ?'),description:t('Elle remplacera le carnet actuel. Exporte ton carnet actuel si tu souhaites garder les deux versions.'),action:()=>{replaceState(recoveryState(recovery.raw));setModal(null);setToast(t('Copie précédente restaurée.'));}})}>{t("Restaurer la copie précédente")}</EditButton>}</div></section>}<NotebookView state={state} onChange={setState} onExport={exportData} onImport={importData} onOpenSource={kind => setModal({ type: 'source', kind })} onOpenDocument={document => setModal({type:'document',document})}/></>}
        <footer className="page-footer"><span><Mountain size={15}/> {t("Le monde, au gré des envies.")}</span><span>{t("Ton voyage évolue. Ton carnet aussi.")} <Heart size={12}/></span></footer>
        </>}
      </main>
    </div>
    <nav className="mobile-bottom-nav glass-selection-group" aria-label={t('Navigation rapide')} inert={!!modal || mobileMenu}>
      <GlassSelection selection={view}/>
      {([{ id: 'planning', label: 'Planning', icon: CalendarDays }, { id: 'map', label: 'Carte', icon: MapIcon }, { id: 'bonus', label: 'Bonus', icon: Sparkles }, { id: 'practical', label: 'Outils', icon: Compass }] as const).map(({ id, label, icon: Icon }) => <button key={id} aria-current={view === id ? 'page' : undefined} onClick={() => navigate(id)}><Icon size={20}/><span>{t(label)}</span></button>)}
      <button aria-label={t('Menu')} aria-expanded={mobileMenu} aria-controls="sidebar" onClick={() => setMobileMenu(true)}><Menu size={20}/><span>{t('Menu')}</span></button>
    </nav>
    {toast && <div className="toast" role="status"><CheckCircle2 size={18}/>{t(toast)}<button onClick={() => setToast('')} aria-label={t("Fermer la notification")}><X size={15}/></button></div>}
    {modal && <Modal title={modal.type === 'city' ? modal.city ? t('Modifier {name}', { name: modal.city.name }) : t('Une nouvelle ville, un nouveau chapitre') : modal.type === 'step' ? modal.step ? t('Modifier cette étape') : t('Ajouter une étape') : modal.type === 'day' ? modal.day ? t('Modifier cette journée') : t('Une nouvelle journée') : modal.type === 'bonus' ? modal.bonus.title : modal.type === 'bonus-editor' ? modal.bonus ? t('Modifier mon adresse') : t('Ajouter une adresse personnelle') : modal.type === 'confirm' ? modal.title : sourceLabel} wide={modal.type === 'source' || modal.type === 'document'} onClose={() => setModal(null)}>
      {modal.type === 'city' && <form onSubmit={cityForm} className="editor-form"><div className="form-row"><label className="field">{t("Ville, région ou lieu de séjour")}<EditInput name="name" required maxLength={100} defaultValue={modal.city?.name} placeholder={t("Ex. Kyoto, Bretagne…")}/></label><label className="field">{t("Nom local (facultatif)")}<EditInput name="chineseName" defaultValue={modal.city?.chineseName} placeholder={t("Dans l’écriture locale")}/></label></div><label className="field">{t("En quelques mots")}<EditInput name="subtitle" defaultValue={modal.city?.subtitle} placeholder={t("Entre jardins secrets et lumières de la ville")}/></label><label className="field">{t("Position dans le voyage")}<EditSelect name="position" defaultValue={modal.city?state.cities.findIndex(c=>c.id===modal.city?.id):state.cities.length}>{Array.from({length:state.cities.length+(modal.city?0:1)},(_,index)=><option value={index} key={index}>{t("Étape")} {index+1}{state.cities[index] && state.cities[index].id!==modal.city?.id ? t(' · avant {city}', { city: state.cities[index].name }) : ''}</option>)}</EditSelect></label><label className="field">{t("Nombre de nuits (facultatif)")}<EditInput name="nights" type="number" min="0" step="1" defaultValue={modal.city?.nights}/></label><label className="field">{t("Fuseau de cette étape (facultatif)")}<EditInput name="timezone" defaultValue={modal.city?.timezone} placeholder={journey.timezone}/></label><label className="field">{t("Pense-bête de la ville")}<EditTextarea category="notes" name="notes" rows={4} defaultValue={modal.city?.notes.join('\n')} placeholder={t("Une information par ligne…")}/></label><p className="muted small">{t("Centre de l’étape sur la carte (facultatif), en coordonnées WGS84. Sans coordonnées, aucun repère n’est inventé.")}</p><div className="form-row"><label className="field">{t("Latitude")}<EditInput name="lat" type="number" step="any" min="-90" max="90" defaultValue={modal.city?.coordinates?.[0]}/></label><label className="field">{t("Longitude")}<EditInput name="lng" type="number" step="any" min="-180" max="180" defaultValue={modal.city?.coordinates?.[1]}/></label></div><div className="form-actions"><button type="button" className="btn btn-secondary" onClick={() => setModal(null)}>{t("Annuler")}</button><EditButton className="btn btn-primary" type="submit"><Check size={16}/> {t("Enregistrer la ville")}</EditButton></div></form>}
      {modal.type === 'day' && <form className="editor-form" onSubmit={dayForm}><label className="field">{t("Le thème de cette journée")}<EditInput name="title" required maxLength={140} defaultValue={modal.day?.title} placeholder={t("Balades, bonnes tables et coucher de soleil")}/></label><label className="field">{t("Date de cette journée (facultative)")}<EditInput type="date" name="date" max="9999-12-30" min="0001-01-01" defaultValue={modal.day?.date}/></label><p className="muted">{t("Les dates sont choisies par journée. Deux villes peuvent partager la même date lors d’un transfert.")}</p><div className="form-actions"><button type="button" className="btn btn-secondary" onClick={() => setModal(null)}>{t("Annuler")}</button><EditButton className="btn btn-primary" type="submit">{t("Enregistrer la journée")}</EditButton></div></form>}
      {modal.type === 'step' && <form className="editor-form" onSubmit={stepForm}><label className="field">{t("Lieu ou activité")}<EditInput name="title" required maxLength={180} defaultValue={modal.step?.title} placeholder={t("Ex. Jardin de l’Humble Administrateur")}/></label><label className="field">{t("Nom local (facultatif)")}<EditInput name="chineseName" defaultValue={modal.step?.chineseName} placeholder={t("Dans l’écriture locale")}/></label><label className="field">{t("Adresse précise")}<EditInput name="address" defaultValue={modal.step?.address} placeholder={t("Rue, numéro et succursale")}/></label><div className="form-row"><label className="field">{t("Catégorie")}<EditSelect name="category" defaultValue={modal.step?.category || 'visit'}>{Object.entries(categoryLabels).filter(([id]) => id !== 'photo').map(([id, label]) => <option key={id} value={id}>{t(label)}</option>)}</EditSelect></label><label className="field">{t("Moment ou horaire")}<EditInput name="period" defaultValue={modal.step?.period} placeholder={t("Ex. En fin d’après-midi")}/></label></div><label className="field">{t("Journée de cette étape")}<EditSelect name="targetDay" defaultValue={modal.day.id}>{city.days.map((d,index)=><option value={d.id} key={d.id}>{t("Jour")} {index+1} · {d.title}</option>)}</EditSelect></label><label className="field">{t("Détails et informations")}<EditTextarea name="description" rows={4} defaultValue={modal.step?.description} placeholder={t("Adresse, trajet, chose à ne pas oublier…")}/></label><div className="form-row"><label className="checkbox-label"><EditInput type="checkbox" name="optional" defaultChecked={modal.step?.optional}/> {t("Facultatif")}</label><label className="checkbox-label"><EditInput type="checkbox" name="booking" defaultChecked={modal.step?.booking}/> {t("À réserver")}</label></div><details className="coordinate-details"><summary>{t("Placer un repère sur la carte (facultatif)")}</summary><p className="muted small">{t("Coordonnées WGS84 uniquement. Sans coordonnées, la recherche cartographique reste disponible.")}</p><div className="form-row"><label className="field">{t("Latitude")}<EditInput name="lat" type="number" step="any" min="-90" max="90" defaultValue={modal.step?.coordinates?.[0]}/></label><label className="field">{t("Longitude")}<EditInput name="lng" type="number" step="any" min="-180" max="180" defaultValue={modal.step?.coordinates?.[1]}/></label></div></details><div className="form-actions"><button type="button" className="btn btn-secondary" onClick={() => setModal(null)}>{t("Annuler")}</button><EditButton className="btn btn-primary" type="submit"><Check size={16}/> {t("Enregistrer l’étape")}</EditButton></div></form>}
      {modal.type === 'bonus' && <div className="bonus-detail"><span className="tag">{t(categoryLabels[modal.bonus.category])} · {city.name}</span>{modal.bonus.chineseName && <p className="detail-chinese">{modal.bonus.chineseName}<button className="icon-btn" aria-label={t("Copier le nom local")} onClick={() => copy(modal.bonus.chineseName!)}><Copy size={15}/></button></p>}<p>{modal.bonus.description}</p>{modal.bonus.address && <div className="detail-address"><MapPin size={18}/><span>{modal.bonus.address}</span><button className="icon-btn" aria-label={t("Copier l’adresse")} onClick={() => copy(modal.bonus.address!)}><Copy size={14}/></button></div>}{modal.bonus.budget && <p><strong>{t("Budget :")}</strong> {modal.bonus.budget}</p>}{modal.bonus.tip && <div className="notice">{modal.bonus.tip}</div>}<div className="detail-actions"><a className="btn btn-primary" href={amapLink(preferredMapCity(city,provider), modal.bonus)} target="_blank" rel="noreferrer"><Navigation size={16}/> {t("Ouvrir dans {map}", {map:mapLabel})} <ExternalLink size={14}/></a><EditButton category="preparation" className="btn btn-secondary" onClick={() => toggleFavorite(modal.bonus.id)}><Heart size={16} fill={state.favorites.includes(modal.bonus.id) ? 'currentColor' : 'none'}/>{state.favorites.includes(modal.bonus.id) ? t('Dans mes favoris') : t('Garder cette envie')}</EditButton></div><div className="bonus-plan-add"><label className="field">{t("Ajouter à mon programme")}<select value={day?.id || ''} onChange={e => setDayId(e.target.value)} aria-label={t("Journée pour ce bonus")}>{!city.days.length && <option value="">{t("Aucune journée pour cette ville")}</option>}{city.days.map((d, i) => <option key={d.id} value={d.id}>{t("Jour {count}", { count: i + 1 })} · {d.title}</option>)}</select></label><EditButton className="btn btn-secondary" disabled={!day} onClick={() => addBonusToDay(modal.bonus)}><Plus size={16}/> {t("Ajouter")}</EditButton></div>{state.customBonus?.some(b=>b.id===modal.bonus.id) && <div className="personal-bonus-actions"><EditButton className="btn btn-secondary" onClick={()=>setModal({type:'bonus-editor',bonus:modal.bonus})}><Pencil size={16}/> {t("Modifier mon adresse")}</EditButton><EditButton className="btn btn-secondary" onClick={()=>setModal({type:'confirm',title:t('Supprimer cette adresse personnelle ?'),description:t('Elle sera retirée de tes bonus et favoris. Les étapes déjà ajoutées au planning sont conservées.'),action:()=>{setState(s=>({...s,customBonus:s.customBonus?.filter(b=>b.id!==modal.bonus.id),favorites:s.favorites.filter(id=>id!==modal.bonus.id)}));setModal(null);}})}><Trash2 size={16}/> {t("Supprimer")}</EditButton></div>}{safeExternalUrl(modal.bonus.sourceUrl) && <a className="text-btn source-link" href={safeExternalUrl(modal.bonus.sourceUrl)} target="_blank" rel="noreferrer">{t("Source citée dans tes notes")} <ExternalLink size={12}/></a>}</div>}
      {modal.type === 'bonus-editor' && <form className="editor-form" onSubmit={bonusForm}><label className="field">{t("Ville")}<EditSelect name="cityId" defaultValue={modal.bonus?.cityId||city.id}>{state.cities.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</EditSelect></label><label className="field">{t("Nom de l’adresse")}<EditInput name="title" required defaultValue={modal.bonus?.title}/></label><label className="field">{t("Nom local (facultatif)")}<EditInput name="chineseName" defaultValue={modal.bonus?.chineseName}/></label><label className="field">{t("Adresse précise")}<EditInput name="address" defaultValue={modal.bonus?.address}/></label><label className="field">{t("Catégorie")}<EditSelect name="category" defaultValue={modal.bonus?.category||'food'}>{['food','photo','visit','shopping'].map(id=><option key={id} value={id}>{t(categoryLabels[id as Bonus['category']])}</option>)}</EditSelect></label><label className="field">{t("Pourquoi y aller ?")}<EditTextarea name="description" rows={3} defaultValue={modal.bonus?.description}/></label><label className="field">{t("Budget indicatif")}<EditInput name="budget" defaultValue={modal.bonus?.budget} placeholder={t("Facultatif, à renseigner")}/></label><label className="field">{t("Conseil personnel")}<EditTextarea category="notes" name="tip" rows={2} defaultValue={modal.bonus?.tip}/></label><div className="form-actions"><EditButton className="btn btn-secondary" type="button" onClick={()=>setModal(null)}>{t("Annuler")}</EditButton><EditButton className="btn btn-primary" type="submit">{t("Enregistrer l’adresse")}</EditButton></div></form>}
      {modal.type === 'document' && <SourceDocument document={modal.document}/>}
      {modal.type === 'source' && <SourceDocument kind={modal.kind}/>}
      {modal.type === 'confirm' && <div className="confirm-dialog"><p>{modal.description}</p><div className="form-actions"><button className="btn btn-secondary" onClick={() => setModal(null)}>{t("Annuler")}</button><EditButton className="btn btn-primary" onClick={modal.action}>{t("Confirmer")}</EditButton></div></div>}
    </Modal>}
  </div></ReadOnlyContext.Provider></SharedFieldsContext.Provider>;
}
